effect.shader:
void main() {
    vec2 offset = (acScreenNorm - 0.5) * vec2(acAspect, 1.0) / max(zoom, 0.01);
    float radius2 = dot(offset, offset);

    vec2 warped = offset * (1.0 + strength * radius2 + fine * radius2 * radius2);
    warped /= vec2(acAspect, 1.0);
    vec2 sampleUv = warped + 0.5;

    // Sem esta verificação, o `clamp` esticaria o pixel da borda por toda a área
    // que sobrou — o que parece um borrão sujo em vez de uma imagem que acabou.
    if (sampleUv.x < 0.0 || sampleUv.x > 1.0 || sampleUv.y < 0.0 || sampleUv.y > 1.0) {
        fragColor = edgeColor;
        return;
    }

    fragColor = texture(inputImg, sampleUv);
}
